def _tools_cli(
    project_path: Path,
    tool_name: str | None,
    tool_argv: list[str],
    *,
    list_only: bool,
    compact: bool,
) -> int:
    """Dispatch `ken tools ...` — a thin CLI over the MCP tool registry.

    The tool list, descriptions, and per-parameter schemas are read live
    from the same ``FastMCP`` object ``ken mcp`` serves, so this stays in
    sync with the MCP surface automatically — there is no second list of
    tools to maintain.
    """
    from ken.mcp import server as mcp_server

    registry = {t.name: t for t in mcp_server.list_tools()}

    if list_only or not tool_name:
        _print_tools_list(registry)
        return 0

    tool = registry.get(tool_name) or registry.get(f"ken_{tool_name}")
    if tool is None:
        import difflib

        print(f"error: unknown tool {tool_name!r}", file=sys.stderr)
        candidates = list(registry) + [
            n[len("ken_") :] for n in registry if n.startswith("ken_")
        ]
        suggestions = difflib.get_close_matches(tool_name, candidates, n=3, cutoff=0.5)
        if suggestions:
            print(f"did you mean: {', '.join(suggestions)}", file=sys.stderr)
        else:
            print("run `ken tools` to list available tools", file=sys.stderr)
        return 2

    tool_parser = _build_tool_parser(tool)
    ns = tool_parser.parse_args(tool_argv)
    props = tool.parameters.get("properties", {})
    kwargs = {name: getattr(ns, name) for name in props if hasattr(ns, name)}

    from ken import _paths

    root = _paths.find_project_root(project_path.resolve()) or project_path.resolve()
    if not _paths.meta_path(root).is_file():
        print(f"error: no .ken project at {root}", file=sys.stderr)
        return 1
    mcp_server._PROJECT_ROOT = root

    try:
        result = tool.fn(**kwargs)
        if tool.is_async:
            import asyncio

            result = asyncio.run(result)
    except Exception as exc:  # surface tool errors as a clean CLI failure
        print(f"error: {tool.name} failed: {exc}", file=sys.stderr)
        return 1

    if compact:
        print(json.dumps(result, default=str))
    else:
        print(json.dumps(result, indent=2, default=str))
    return 0


def _print_tools_list(registry: dict[str, Any]) -> None:
    width = max((len(n) for n in registry), default=0)
    for name in sorted(registry):
        summary = _first_doc_line(registry[name].description)
        print(f"  {name:<{width}}  {summary}")
    print("\nRun `ken tools <name> --help` for a tool's parameters.")


def _first_doc_line(text: str | None) -> str:
    for line in (text or "").splitlines():
        stripped = line.strip()
        if stripped:
            return stripped
    return ""


def _tool_schema_core(prop: dict[str, Any]) -> dict[str, Any]:
    """Collapse an ``anyOf: [T, null]`` (Optional[T]) schema to just ``T``."""
    if "anyOf" in prop:
        for variant in prop["anyOf"]:
            if variant.get("type") != "null":
                return variant
    return prop


def _tool_py_type(json_type: str | None):
    if json_type == "object":
        return _tool_json_object
    if json_type is None:
        return str
    return {"integer": int, "number": float, "string": str}.get(json_type, str)


def _tool_json_object(value: str) -> dict[str, Any]:
    """Decode object parameters, including each item of an array of objects."""
    try:
        parsed = json.loads(value)
    except (ValueError, RecursionError) as exc:
        raise argparse.ArgumentTypeError("expected a JSON object") from exc
    if not isinstance(parsed, dict):
        raise argparse.ArgumentTypeError("expected a JSON object")
    return parsed


def _build_tool_parser(tool: Any) -> argparse.ArgumentParser:
    """Build an argparse parser for one tool from its JSON schema.

    Required parameters become positionals (in schema order); optional
    ones become ``--flags`` whose defaults mirror the function signature.
    This gives every tool a real ``--help`` for free.
    """
    props: dict[str, Any] = tool.parameters.get("properties", {})
    required = set(tool.parameters.get("required", []))
    parser = argparse.ArgumentParser(
        prog=f"ken tools {tool.name}",
        description=(tool.description or "").strip() or None,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    for name, prop in props.items():
        core = _tool_schema_core(prop)
        json_type = core.get("type")
        default = prop.get("default")
        is_required = name in required
        flag = "--" + name.replace("_", "-")

        # ken_find's query became optional for saved-rule searches. Preserve
        # the existing positional CLI while allowing query-free MCP calls.
        if tool.name == "ken_find" and name == "query" and not is_required:
            parser.add_argument(name, nargs="?", default=argparse.SUPPRESS)
            parser.add_argument(flag, dest=name, default=default)
            continue
        if json_type == "boolean":
            parser.add_argument(
                flag,
                dest=name,
                action=argparse.BooleanOptionalAction,
                default=default,
                help=f"boolean (default: {default})",
            )
        elif json_type == "array":
            item_type = _tool_py_type(core.get("items", {}).get("type"))
            if is_required:
                parser.add_argument(
                    name, nargs="+", type=item_type, help="list (required)"
                )
            else:
                parser.add_argument(
                    flag,
                    dest=name,
                    nargs="*",
                    type=item_type,
                    default=default,
                    help="space-separated list",
                )
        else:
            py_type = _tool_py_type(json_type)
            if is_required:
                parser.add_argument(
                    name, type=py_type, help=f"{json_type or 'string'} (required)"
                )
            else:
                parser.add_argument(
                    flag,
                    dest=name,
                    type=py_type,
                    default=default,
                    help=f"{json_type or 'string'} (default: {default!r})",
                )
    return parser

class ToolDef:
    """Lightweight record of a registered MCP tool.

    Mirrors the public surface of the old ``fastmcp.Tool`` object that
    ``ken tools ...`` was reading via ``mcp._tool_manager.list_tools()``:
    ``name``, ``description``, ``parameters`` (JSON schema), ``fn``, and
    ``is_async``.
    """

    name: str
    description: str
    fn: Callable[..., Any]
    is_async: bool
    parameters: dict[str, Any]
    input_schema: dict[str, Any]


_REGISTRY: dict[str, ToolDef] = {}


def _register(fn: Callable[..., Any]) -> Callable[..., Any]:
    """Build a ``ToolDef`` from a function and stash it in ``_REGISTRY``.

    The function name becomes the tool name (callers use the
    ``ken_foo`` convention themselves). The JSON schema is derived from
    the function's signature — annotations become ``properties``,
    parameters with defaults become optional, the rest required. This is
    the same shape the SDK derives internally, so any agent that reads
    those schemas sees the same surface either way.
    """
    sig = inspect.signature(fn)
    # Resolve string annotations (``from __future__ import annotations``
    # makes every annotation a forward-reference string at runtime; we
    # need the real type object to map it to a JSON schema).
    # ``inspect.get_annotations(..., eval_str=True)`` evaluates those
    # strings against the function's own ``__globals__``, which is what
    # the SDK does internally to build its own tool schema.
    try:
        hints = inspect.get_annotations(fn, eval_str=True)
    except Exception:
        # Fallback for unresolvable forward refs: leave the annotation as-is.
        hints = {}
    properties: dict[str, Any] = {}
    required: list[str] = []
    for name, param in sig.parameters.items():
        if name == "self":
            continue
        annotation = hints.get(name, param.annotation)
        prop, has_default = _annotation_to_schema(param, annotation)
        if prop is None:
            continue
        if not has_default:
            required.append(name)
        properties[name] = prop

    schema: dict[str, Any] = {
        "type": "object",
        "properties": properties,
    }
    if required:
        schema["required"] = required

    _REGISTRY[fn.__name__] = ToolDef(
        name=fn.__name__,
        description=(fn.__doc__ or "").strip(),
        fn=fn,
        is_async=inspect.iscoroutinefunction(fn),
        parameters=schema,
        input_schema=schema,
    )
    return fn


def ken_tool(fn: Callable[..., Any]) -> Callable[..., Any]:
    """Register ``fn`` as both an MCP tool and a CLI-passthrough tool."""
    mcp.add_tool(fn)
    _register(fn)
    return fn


def list_tools() -> list[ToolDef]:
    """Snapshot of every registered tool, in insertion order."""
    return list(_REGISTRY.values())


# ── JSON-Schema derivation ─────────────────────────────────────────────
#
# Mirrors what the SDK's MCPServer does internally — narrowly, only for
# the annotation shapes ken actually uses (``str``, ``int``, ``float``,
# ``bool``, ``list[...]``, ``dict[...]``, ``X | None`` / ``Optional[X]``).

_PRIMITIVE_JSON_TYPE = {
    str: "string",
    int: "integer",
    float: "number",
    bool: "boolean",
}


def _annotation_to_schema(
    param: inspect.Parameter,
    annotation: Any | None = None,
) -> tuple[dict[str, Any] | None, bool]:
    """Return ``(schema_dict, has_default)`` for a single function parameter.

    ``has_default`` is True when the parameter is optional in the JSON
    schema sense — either it has a Python default or its annotation is
    ``Optional[X]`` / ``X | None``. Returns ``(None, True)`` for
    ``*args`` / ``**kwargs`` / ``self``, which are not part of the schema.

    ``annotation`` overrides ``param.annotation`` when given — callers that
    already resolved string forward references (e.g. from
    ``inspect.get_annotations(eval_str=True)``) pass the resolved type here
    so this helper doesn't have to know about module globals.
    """
    if param.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):
        return None, True

    has_default = param.default is not inspect.Parameter.empty
    if annotation is None:
        annotation = param.annotation

    core, is_optional = _unwrap_optional(annotation)
    if is_optional:
        has_default = True

    if core is inspect.Parameter.empty or core is None:
        schema: dict[str, Any] = {}
    elif core in _PRIMITIVE_JSON_TYPE:
        schema = {"type": _PRIMITIVE_JSON_TYPE[core]}
    elif origin := typing.get_origin(core):
        if origin is typing.Literal:
            schema = _literal_schema(core)
        elif origin in (list, typing.List):
            schema = {"type": "array", "items": _items_schema(typing.get_args(core))}
        elif origin in (dict, typing.Dict):
            schema = {"type": "object"}
        else:
            schema = {}
    elif isinstance(core, type):
        schema = {"type": "string"}  # named types → opaque string for the agent
    else:
        schema = {}

    if param.default is not inspect.Parameter.empty and param.default is not None:
        schema["default"] = param.default

    return schema, has_default


def _unwrap_optional(annotation: Any) -> tuple[Any, bool]:
    """Return ``(inner, is_optional)`` for ``X | None`` / ``Optional[X]`` / ``None``."""
    if annotation is None or annotation is type(None):
        return type(None), True
    origin = typing.get_origin(annotation)
    # Both spellings of a union reach here. ``Optional[X]`` reports
    # ``typing.Union``; PEP 604's ``X | None`` reports ``types.UnionType``,
    # a genuinely different object until Python 3.14 unifies them. Matching
    # only the first silently degrades every ``X | None`` parameter to an
    # empty schema.
    if origin is typing.Union or origin is types.UnionType:
        args = [a for a in typing.get_args(annotation) if a is not type(None)]
        if len(args) == 1 and len(typing.get_args(annotation)) > 1:
            return args[0], True
        return annotation, False
    return annotation, False


def _literal_schema(core: Any) -> dict[str, Any]:
    """``Literal[...]`` → a JSON ``enum``, typed when the values agree.

    A closed set of values is the difference between a menu and free-form
    generation. Without the ``enum``, an agent has to guess what a mode
    argument accepts from prose that a host's description compression may
    already have trimmed — which is strictly worse than having been handed
    separate named tools.
    """
    values = list(typing.get_args(core))
    schema: dict[str, Any] = {"enum": values}
    kinds = {type(v) for v in values}
    if len(kinds) == 1:
        only = kinds.pop()
        if only in _PRIMITIVE_JSON_TYPE:
            schema["type"] = _PRIMITIVE_JSON_TYPE[only]
    return schema


def _items_schema(args: tuple[Any, ...]) -> dict[str, Any]:
    if not args:
        return {}
    inner, _ = _unwrap_optional(args[0])
    if inner in _PRIMITIVE_JSON_TYPE:
        return {"type": _PRIMITIVE_JSON_TYPE[inner]}
    if typing.get_origin(inner) is dict:
        return {"type": "object"}
    if typing.get_origin(inner) is list:
        return {"type": "array", "items": _items_schema(typing.get_args(inner))}
    if typing.get_origin(inner) is typing.Literal:
        # ``list[Literal[...]]`` — the element enum is the only place that
        # says which values the list may hold.
        return _literal_schema(inner)
    return {}
